import { randomUUID } from 'node:crypto'

import { type AppConfig, isSupabaseConfigured, loadConfig } from '../../config/index.js'
import { getSupabaseAdmin } from '../../database/index.js'
import {
  type CreateInvoiceInput,
  formatInvoiceNumber,
  type InvoiceRecord,
  type InvoiceStatus,
  type UpdateInvoiceInput,
} from './invoices.types.js'

export type InvoicesRepository = {
  /** Insert a numbered invoice (number is generated by the DB from `invoice_seq`). */
  create: (input: CreateInvoiceInput) => Promise<InvoiceRecord>
  findById: (id: string) => Promise<InvoiceRecord | null>
  /** The payment's non-voided invoice, if any. */
  findActiveByPaymentId: (paymentId: string) => Promise<InvoiceRecord | null>
  /** Every invoice (voided included) for the payments, oldest first. */
  listByPaymentIds: (paymentIds: string[]) => Promise<InvoiceRecord[]>
  update: (id: string, input: UpdateInvoiceInput) => Promise<InvoiceRecord | null>
  /** Marks a non-voided invoice voided; null if it was already voided or missing. */
  void: (id: string, reason: string) => Promise<InvoiceRecord | null>
}

type InvoiceRow = {
  id: string
  payment_id: string
  invoice_seq: number | string
  invoice_number: string
  invoice_date: string | null
  invoice_status: InvoiceStatus | null
  amount: number | string
  currency: string
  pdf_path: string | null
  sent_at: string | null
  last_error: string | null
  voided_at: string | null
  void_reason: string | null
  created_at: string
  updated_at: string
}

const INVOICE_COLUMNS =
  'id, payment_id, invoice_seq, invoice_number, invoice_date, invoice_status, amount, currency, pdf_path, sent_at, last_error, voided_at, void_reason, created_at, updated_at'

function fromRow(row: InvoiceRow): InvoiceRecord {
  return {
    id: row.id,
    paymentId: row.payment_id,
    invoiceSeq: Number(row.invoice_seq),
    invoiceNumber: row.invoice_number,
    invoiceDate: row.invoice_date,
    invoiceStatus: row.invoice_status,
    amount: Number(row.amount),
    currency: row.currency,
    pdfPath: row.pdf_path,
    sentAt: row.sent_at,
    lastError: row.last_error,
    voidedAt: row.voided_at,
    voidReason: row.void_reason,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  }
}

const memoryInvoices: InvoiceRecord[] = []
let memorySeq = 0

export function resetInvoicesRepositoryForTests(): void {
  memoryInvoices.length = 0
  memorySeq = 0
}

function createMemoryInvoicesRepository(): InvoicesRepository {
  function replace(index: number, patch: Partial<InvoiceRecord>): InvoiceRecord {
    const updated = { ...memoryInvoices[index]!, ...patch, updatedAt: new Date().toISOString() }
    memoryInvoices[index] = updated
    return updated
  }

  return {
    async create(input) {
      if (memoryInvoices.some((row) => row.paymentId === input.paymentId && !row.voidedAt)) {
        throw Object.assign(new Error('duplicate active invoice'), { code: '23505' })
      }
      memorySeq += 1
      const stamp = new Date().toISOString()
      const invoice: InvoiceRecord = {
        id: randomUUID(),
        paymentId: input.paymentId,
        invoiceSeq: memorySeq,
        invoiceNumber: formatInvoiceNumber(memorySeq),
        invoiceDate: stamp,
        invoiceStatus: null,
        amount: input.amount,
        currency: input.currency,
        pdfPath: null,
        sentAt: null,
        lastError: null,
        voidedAt: null,
        voidReason: null,
        createdAt: stamp,
        updatedAt: stamp,
      }
      memoryInvoices.push(invoice)
      return invoice
    },
    async findById(id) {
      return memoryInvoices.find((row) => row.id === id) ?? null
    },
    async findActiveByPaymentId(paymentId) {
      return memoryInvoices.find((row) => row.paymentId === paymentId && !row.voidedAt) ?? null
    },
    async listByPaymentIds(paymentIds) {
      const wanted = new Set(paymentIds)
      return memoryInvoices
        .filter((row) => wanted.has(row.paymentId))
        .sort((a, b) => a.invoiceSeq - b.invoiceSeq)
    },
    async update(id, input) {
      const index = memoryInvoices.findIndex((row) => row.id === id)
      if (index === -1) return null
      const current = memoryInvoices[index]!
      return replace(index, {
        invoiceDate: input.invoiceDate ?? current.invoiceDate,
        invoiceStatus: input.invoiceStatus ?? current.invoiceStatus,
        pdfPath: input.pdfPath !== undefined ? input.pdfPath : current.pdfPath,
        sentAt: input.sentAt !== undefined ? input.sentAt : current.sentAt,
        lastError: input.lastError !== undefined ? input.lastError : current.lastError,
      })
    },
    async void(id, reason) {
      const index = memoryInvoices.findIndex((row) => row.id === id && !row.voidedAt)
      if (index === -1) return null
      return replace(index, { voidedAt: new Date().toISOString(), voidReason: reason })
    },
  }
}

function createSupabaseInvoicesRepository(config: AppConfig): InvoicesRepository {
  const supabase = getSupabaseAdmin(config)
  if (!supabase) {
    throw new Error('Supabase admin client is not available')
  }
  const client = supabase

  return {
    async create(input) {
      const { data, error } = await client
        .from('invoices')
        .insert({
          payment_id: input.paymentId,
          amount: input.amount,
          currency: input.currency,
          invoice_date: new Date().toISOString(),
        })
        .select(INVOICE_COLUMNS)
        .single()
      if (error) throw error
      return fromRow(data as InvoiceRow)
    },
    async findById(id) {
      const { data, error } = await client
        .from('invoices')
        .select(INVOICE_COLUMNS)
        .eq('id', id)
        .maybeSingle()
      if (error) throw error
      return data ? fromRow(data as InvoiceRow) : null
    },
    async findActiveByPaymentId(paymentId) {
      const { data, error } = await client
        .from('invoices')
        .select(INVOICE_COLUMNS)
        .eq('payment_id', paymentId)
        .is('voided_at', null)
        .maybeSingle()
      if (error) throw error
      return data ? fromRow(data as InvoiceRow) : null
    },
    async listByPaymentIds(paymentIds) {
      if (paymentIds.length === 0) return []
      const { data, error } = await client
        .from('invoices')
        .select(INVOICE_COLUMNS)
        .in('payment_id', paymentIds)
        .order('invoice_seq', { ascending: true })
      if (error) throw error
      return (data as InvoiceRow[]).map(fromRow)
    },
    async update(id, input) {
      const patch: Record<string, unknown> = {}
      if (input.invoiceDate !== undefined) patch.invoice_date = input.invoiceDate
      if (input.invoiceStatus !== undefined) patch.invoice_status = input.invoiceStatus
      if (input.pdfPath !== undefined) patch.pdf_path = input.pdfPath
      if (input.sentAt !== undefined) patch.sent_at = input.sentAt
      if (input.lastError !== undefined) patch.last_error = input.lastError
      const { data, error } = await client
        .from('invoices')
        .update(patch)
        .eq('id', id)
        .select(INVOICE_COLUMNS)
        .maybeSingle()
      if (error) throw error
      return data ? fromRow(data as InvoiceRow) : null
    },
    async void(id, reason) {
      const { data, error } = await client
        .from('invoices')
        .update({ voided_at: new Date().toISOString(), void_reason: reason })
        .eq('id', id)
        .is('voided_at', null)
        .select(INVOICE_COLUMNS)
        .maybeSingle()
      if (error) throw error
      return data ? fromRow(data as InvoiceRow) : null
    },
  }
}

export function createInvoicesRepository(config: AppConfig = loadConfig()): InvoicesRepository {
  if (isSupabaseConfigured(config)) {
    return createSupabaseInvoicesRepository(config)
  }
  return createMemoryInvoicesRepository()
}
